<?php
require_once __DIR__.'/../identity/OfficePolicy.php';
final class StaffPDSEntry {
 public static function actor(PDO $db,int $actor):array{$a=OfficePolicy::actor($db,$actor);if(!in_array($a['role'],['admin','guidance_advocate','super_admin'],true))throw new RuntimeException('Only authorized guidance staff can enter a paper PDS.');return $a;}
 public static function context(PDO $db,int $actor,int $owner):array{self::actor($db,$actor);$q=$db->prepare("SELECT id,role,first_name,middle_name,last_name,email FROM users WHERE id=? AND role='student' AND is_active=1 AND COALESCE(archived,0)=0");$q->execute([$owner]);$student=$q->fetch(PDO::FETCH_ASSOC);if(!$student)throw new RuntimeException('Choose an active student account.');foreach(['pds','pds_versions'] as $table){$q=$db->prepare("SELECT 1 FROM $table WHERE user_id=? LIMIT 1");$q->execute([$owner]);if($q->fetchColumn())throw new RuntimeException('This student already has a digital PDS or PDS history. Open the existing record instead.');}return ['actor_id'=>$actor,'student'=>$student];}
 public static function students(PDO $db,int $actor,string $search=''):array{self::actor($db,$actor);if(mb_strlen($search)>100)throw new InvalidArgumentException('Use a shorter student search.');$where="u.role='student' AND u.is_active=1 AND COALESCE(u.archived,0)=0 AND NOT EXISTS(SELECT 1 FROM pds p WHERE p.user_id=u.id) AND NOT EXISTS(SELECT 1 FROM pds_versions v WHERE v.user_id=u.id)";$args=[];if(trim($search)!==''){$where.=' AND (CONCAT_WS(\' \',u.first_name,u.last_name) LIKE ? OR sp.student_id LIKE ?)';$args=['%'.trim($search).'%','%'.trim($search).'%'];}$q=$db->prepare("SELECT u.id,u.first_name,u.last_name,sp.student_id,sp.department,sp.grade_level FROM users u LEFT JOIN student_profiles sp ON sp.user_id=u.id WHERE $where ORDER BY u.last_name,u.first_name,u.id LIMIT 10");$q->execute($args);return $q->fetchAll(PDO::FETCH_ASSOC);}
}
